//! Recipes (PLAN.md 10.4): PMMP's recipes as static tables generated by `cargo xtask gen`, and the
//! `CraftingData` packet built from them the way PMMP's `CraftingDataCache` builds it.
//!
//! Matching crafting grids against the recipes is M7.

mod table;

use crate::item::{self, Type};
use crate::nbt::StaticCompound;
use crate::protocol::packet::CraftingData;
use crate::protocol::{
    DefaultItemDescriptor, InvalidItemDescriptor, ItemDescriptor, ItemDescriptorCount, ItemStack,
    ItemTagItemDescriptor, PotionContainerChangeRecipe, PotionRecipe, RecipeUnlockRequirement,
    ShapedRecipe, ShapelessRecipe, SmithingTransformRecipe, SmithingTrimRecipe, Uuid,
};

/// The meta of an ingredient that matches every meta (PMMP
/// `TypeConverter::RECIPE_INPUT_WILDCARD_META`).
const WILDCARD_META: i32 = 0x7fff;

/// The priority PMMP's `CraftingDataCache` gives every crafting and furnace recipe.
const PRIORITY: i32 = 50;

/// gophertunnel `RecipeUnlockContextAlwaysUnlocked`.
const UNLOCK_ALWAYS: i32 = 1;

/// The block name of smithing recipes, as BDS and dragonfly send it.
const SMITHING_TABLE: &str = "smithing_table";

/// An item stack of a recipe result.
#[derive(Debug, Clone, Copy)]
pub(crate) struct Stack {
    item: Type,
    /// The stack's meta, which PMMP sends. It differs from the type's meta where PMMP reads meta
    /// as stack state (a firework star's colour).
    meta: u16,
    count: u16,
    /// The stack NBT as PMMP holds it (a banner's `Type`, a firework's explosions).
    nbt: Option<StaticCompound>,
}

/// An ingredient that matches one item type (PMMP `ExactRecipeIngredient`). The stack NBT PMMP
/// also compares is left out until crafting is matched (M7); the network form does not carry it.
#[derive(Debug, Clone, Copy)]
pub(crate) struct Exact {
    item: Type,
    /// The meta PMMP sends: the legacy meta of the block state for a block item, the stack meta
    /// otherwise (`TypeConverter::coreRecipeIngredientToNet`).
    network_meta: i32,
}

/// An item name with its runtime ID.
#[derive(Debug, Clone, Copy)]
pub(crate) struct Name {
    name: &'static str,
    runtime_id: i16,
}

/// A recipe ingredient (PMMP `RecipeIngredient`).
#[derive(Debug, Clone, Copy)]
pub(crate) enum Ingredient {
    Exact(Exact),
    /// Any item of the name, whatever its meta (PMMP `MetaWildcardRecipeIngredient`).
    AnyMeta(Name),
    /// Any item with the item tag (PMMP `TagWildcardRecipeIngredient`).
    Tag(&'static str),
}

/// The block a shapeless recipe is made in (PMMP `ShapelessRecipeType`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum ShapelessType {
    Crafting,
    Stonecutter,
}

/// The block a furnace recipe is made in (PMMP `FurnaceType`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum FurnaceType {
    Furnace,
    BlastFurnace,
    Smoker,
    Campfire,
    SoulCampfire,
}

/// A shaped crafting recipe.
#[derive(Debug)]
pub(crate) struct Shaped {
    width: u8,
    height: u8,
    /// Row-major, `width * height` cells; `None` is an empty cell.
    grid: &'static [Option<Ingredient>],
    results: &'static [Stack],
}

/// A shapeless recipe.
#[derive(Debug)]
pub(crate) struct Shapeless {
    kind: ShapelessType,
    ingredients: &'static [Ingredient],
    results: &'static [Stack],
}

/// A furnace recipe.
#[derive(Debug)]
pub(crate) struct Furnace {
    kind: FurnaceType,
    input: Ingredient,
    result: Stack,
}

/// A brewing recipe that changes the potion type.
#[derive(Debug)]
pub(crate) struct PotionType {
    input: Exact,
    reagent: Exact,
    output: Stack,
}

/// A brewing recipe that changes the potion container (potion to splash potion and so on).
#[derive(Debug)]
pub(crate) struct PotionContainerChange {
    input: Name,
    reagent: Exact,
    output: Name,
}

/// A smithing recipe that turns the input into the result.
#[derive(Debug)]
pub(crate) struct SmithingTransform {
    template: Ingredient,
    input: Ingredient,
    addition: Ingredient,
    result: Stack,
}

/// A smithing recipe that puts an armor trim on the input.
#[derive(Debug)]
pub(crate) struct SmithingTrim {
    template: Ingredient,
    input: Ingredient,
    addition: Ingredient,
}

impl Stack {
    /// A stack of the item type with this table index. Only the generated table calls it.
    const fn new(item: u16, meta: u16, count: u16, nbt: Option<StaticCompound>) -> Self {
        Self {
            item: Type::from_index(item),
            meta,
            count,
            nbt,
        }
    }

    /// The network form (PMMP `TypeConverter::coreItemStackToNet`), with the stack's meta.
    fn network(&self) -> ItemStack {
        item::network_stack(self.item, self.meta, self.count, self.nbt)
    }
}

impl Exact {
    /// An ingredient of the item type with this table index. Only the generated table calls it.
    const fn new(item: u16, network_meta: i32) -> Self {
        Self {
            item: Type::from_index(item),
            network_meta,
        }
    }
}

impl Name {
    const fn new(name: &'static str, runtime_id: i16) -> Self {
        Self { name, runtime_id }
    }
}

impl ShapelessType {
    /// PMMP `CraftingRecipeBlockName`.
    const fn block_name(self) -> &'static str {
        match self {
            Self::Crafting => "crafting_table",
            Self::Stonecutter => "stonecutter",
        }
    }
}

impl FurnaceType {
    /// PMMP `FurnaceRecipeBlockName`.
    const fn block_name(self) -> &'static str {
        match self {
            Self::Furnace => "furnace",
            Self::BlastFurnace => "blast_furnace",
            Self::Smoker => "smoker",
            Self::Campfire => "campfire",
            Self::SoulCampfire => "soul_campfire",
        }
    }
}

/// The `CraftingData` packet of every recipe. The server builds it once at start; it is the same
/// for every player.
///
/// It follows PMMP's `CraftingDataCache`: crafting recipes get network IDs from 1, furnace
/// recipes continue the count, every recipe has the nil UUID, priority 50 and is always unlocked,
/// no multi recipes are sent and `clear_recipes` is set. PMMP sends no smithing recipes; Anchor
/// sends them like dragonfly, continuing the count after the furnace recipes.
pub(crate) fn crafting_data() -> CraftingData {
    let mut last_id: u32 = 0;
    // A few thousand static recipes cannot reach `u32::MAX`.
    let mut next_id = || {
        last_id = last_id.saturating_add(1);
        last_id
    };
    let shaped_recipes = table::SHAPED.iter().map(|r| r.network(next_id())).collect();
    let mut shapeless_recipes: Vec<ShapelessRecipe> =
        Vec::with_capacity(table::SHAPELESS.len() + table::FURNACE.len());
    for r in &table::SHAPELESS {
        shapeless_recipes.push(shapeless(
            next_id(),
            r.ingredients.iter().map(|i| descriptor(Some(i))).collect(),
            r.results.iter().map(Stack::network).collect(),
            r.kind.block_name(),
        ));
    }
    // PMMP sends furnace recipes as shapeless recipes of the furnace block.
    for r in &table::FURNACE {
        shapeless_recipes.push(shapeless(
            next_id(),
            vec![descriptor(Some(&r.input))],
            vec![r.result.network()],
            r.kind.block_name(),
        ));
    }
    let smithing_transform_recipes = table::SMITHING_TRANSFORM
        .iter()
        .map(|r| r.network(next_id()))
        .collect();
    let smithing_trim_recipes = table::SMITHING_TRIM
        .iter()
        .map(|r| r.network(next_id()))
        .collect();
    let potion_recipes = table::POTION_TYPE.iter().map(PotionType::network).collect();
    let potion_container_change_recipes = table::POTION_CONTAINER_CHANGE
        .iter()
        .map(PotionContainerChange::network)
        .collect();
    CraftingData {
        shaped_recipes,
        shapeless_recipes,
        smithing_transform_recipes,
        smithing_trim_recipes,
        potion_recipes,
        potion_container_change_recipes,
        clear_recipes: true,
        ..CraftingData::default()
    }
}

impl Shaped {
    /// The network form, as PMMP's `CraftingDataCache` writes it.
    fn network(&self, id: u32) -> ShapedRecipe {
        ShapedRecipe {
            recipe_id: recipe_id(id),
            width: i32::from(self.width),
            height: i32::from(self.height),
            input: self.grid.iter().map(|i| descriptor(i.as_ref())).collect(),
            output: self.results.iter().map(Stack::network).collect(),
            uuid: Uuid::default(),
            block: ShapelessType::Crafting.block_name().to_owned(),
            priority: PRIORITY,
            // PMMP writes the symmetry flag as true.
            assume_symmetry: true,
            unlock_requirement: Some(always_unlocked()),
            recipe_network_id: id,
        }
    }
}

impl SmithingTransform {
    /// The network form, as dragonfly writes it.
    fn network(&self, id: u32) -> SmithingTransformRecipe {
        SmithingTransformRecipe {
            recipe_network_id: id,
            recipe_id: recipe_id(id),
            template: descriptor(Some(&self.template)),
            base: descriptor(Some(&self.input)),
            addition: descriptor(Some(&self.addition)),
            result: self.result.network(),
            block: SMITHING_TABLE.to_owned(),
        }
    }
}

impl SmithingTrim {
    /// The network form, as dragonfly writes it.
    fn network(&self, id: u32) -> SmithingTrimRecipe {
        SmithingTrimRecipe {
            recipe_network_id: id,
            recipe_id: recipe_id(id),
            template: descriptor(Some(&self.template)),
            base: descriptor(Some(&self.input)),
            addition: descriptor(Some(&self.addition)),
            block: SMITHING_TABLE.to_owned(),
        }
    }
}

impl PotionType {
    /// The network form: runtime IDs and the metas PMMP sends.
    fn network(&self) -> PotionRecipe {
        PotionRecipe {
            input_potion_id: i32::from(self.input.item.runtime_id()),
            input_potion_metadata: self.input.network_meta,
            reagent_item_id: i32::from(self.reagent.item.runtime_id()),
            reagent_item_metadata: self.reagent.network_meta,
            output_potion_id: i32::from(self.output.item.runtime_id()),
            output_potion_metadata: i32::from(self.output.meta),
        }
    }
}

impl PotionContainerChange {
    /// The network form: runtime IDs only.
    fn network(&self) -> PotionContainerChangeRecipe {
        PotionContainerChangeRecipe {
            input_item_id: i32::from(self.input.runtime_id),
            reagent_item_id: i32::from(self.reagent.item.runtime_id()),
            output_item_id: i32::from(self.output.runtime_id),
        }
    }
}

/// A shapeless recipe entry as PMMP writes one.
fn shapeless(
    id: u32,
    input: Vec<ItemDescriptorCount>,
    output: Vec<ItemStack>,
    block: &str,
) -> ShapelessRecipe {
    ShapelessRecipe {
        recipe_id: recipe_id(id),
        input,
        output,
        uuid: Uuid::default(),
        block: block.to_owned(),
        priority: PRIORITY,
        unlock_requirement: Some(always_unlocked()),
        recipe_network_id: id,
    }
}

/// The recipe identifier: the network ID in decimal. PMMP sends the network ID's four big-endian
/// bytes, which are not always valid UTF-8; the decimal form is the same unique value as text.
fn recipe_id(id: u32) -> String {
    id.to_string()
}

/// PMMP sends `RecipeUnlockingRequirement(null)`, which its 1.26.30 protocol writes as the
/// "always unlocked" context; 1.26.40 wrapped the requirement in an optional.
fn always_unlocked() -> RecipeUnlockRequirement {
    RecipeUnlockRequirement {
        context: UNLOCK_ALWAYS,
        ingredients: Vec::new(),
    }
}

/// The network form of an ingredient (PMMP `TypeConverter::coreRecipeIngredientToNet`): an empty
/// cell is the invalid descriptor with count 0, everything else has count 1. Since 1.26.40 the
/// default descriptor names the item instead of giving its runtime ID.
fn descriptor(ingredient: Option<&Ingredient>) -> ItemDescriptorCount {
    let default = |name: &str, meta: i32| {
        ItemDescriptor::Default(DefaultItemDescriptor {
            name: name.to_owned(),
            metadata_value: meta,
        })
    };
    let descriptor = match ingredient {
        None => {
            return ItemDescriptorCount {
                descriptor: ItemDescriptor::Invalid(InvalidItemDescriptor {}),
                count: 0,
            };
        }
        Some(Ingredient::Exact(e)) => default(e.item.name(), e.network_meta),
        Some(Ingredient::AnyMeta(n)) => default(n.name, WILDCARD_META),
        Some(Ingredient::Tag(tag)) => ItemDescriptor::ItemTag(ItemTagItemDescriptor {
            tag: (*tag).to_owned(),
        }),
    };
    ItemDescriptorCount {
        descriptor,
        count: 1,
    }
}

#[cfg(test)]
mod tests {
    use std::collections::BTreeSet;

    use serde_json::Value as Json;

    use super::*;
    use crate::protocol::packet::Packet;

    /// The PMMP recipe dump the tables come from.
    fn dump() -> Json {
        let text = include_str!("../xtask/data/pmmp/recipes.json");
        serde_json::from_str(text).unwrap()
    }

    /// The reference item list: runtime ID by name.
    fn reference_ids() -> std::collections::BTreeMap<String, i16> {
        let text = include_str!("../xtask/data/reference/items.json");
        let list: Vec<Json> = serde_json::from_str(text).unwrap();
        list.iter()
            .map(|i| {
                (
                    i["name"].as_str().unwrap().to_owned(),
                    i16::try_from(i["runtime_id"].as_i64().unwrap()).unwrap(),
                )
            })
            .collect()
    }

    fn len(dump: &Json, kind: &str) -> usize {
        dump[kind].as_array().unwrap().len()
    }

    /// Every item type and name a recipe uses.
    fn all_ingredients() -> Vec<Ingredient> {
        let mut out = Vec::new();
        for r in &table::SHAPED {
            out.extend(r.grid.iter().flatten().copied());
        }
        for r in &table::SHAPELESS {
            out.extend(r.ingredients.iter().copied());
        }
        for r in &table::FURNACE {
            out.push(r.input);
        }
        for r in &table::POTION_TYPE {
            out.push(Ingredient::Exact(r.input));
            out.push(Ingredient::Exact(r.reagent));
        }
        for r in &table::POTION_CONTAINER_CHANGE {
            out.push(Ingredient::AnyMeta(r.input));
            out.push(Ingredient::Exact(r.reagent));
            out.push(Ingredient::AnyMeta(r.output));
        }
        for r in &table::SMITHING_TRANSFORM {
            out.extend([r.template, r.input, r.addition]);
        }
        for r in &table::SMITHING_TRIM {
            out.extend([r.template, r.input, r.addition]);
        }
        out
    }

    fn all_results() -> Vec<Stack> {
        let mut out = Vec::new();
        for r in &table::SHAPED {
            out.extend(r.results.iter().copied());
        }
        for r in &table::SHAPELESS {
            out.extend(r.results.iter().copied());
        }
        out.extend(table::FURNACE.iter().map(|r| r.result));
        out.extend(table::POTION_TYPE.iter().map(|r| r.output));
        out.extend(table::SMITHING_TRANSFORM.iter().map(|r| r.result));
        out
    }

    #[test]
    fn tables_hold_every_dumped_recipe() {
        let dump = dump();
        assert_eq!(table::SHAPED.len(), len(&dump, "shaped"));
        assert_eq!(table::SHAPELESS.len(), len(&dump, "shapeless"));
        assert_eq!(table::FURNACE.len(), len(&dump, "furnace"));
        assert_eq!(table::POTION_TYPE.len(), len(&dump, "potion_type"));
        assert_eq!(
            table::POTION_CONTAINER_CHANGE.len(),
            len(&dump, "potion_container_change")
        );
        assert_eq!(
            table::SMITHING_TRANSFORM.len(),
            len(&dump, "smithing_transform")
        );
        assert_eq!(table::SMITHING_TRIM.len(), len(&dump, "smithing_trim"));

        let packet = crafting_data();
        assert_eq!(packet.shaped_recipes.len(), table::SHAPED.len());
        assert_eq!(
            packet.shapeless_recipes.len(),
            table::SHAPELESS.len() + table::FURNACE.len()
        );
        assert_eq!(packet.potion_recipes.len(), table::POTION_TYPE.len());
        assert_eq!(
            packet.potion_container_change_recipes.len(),
            table::POTION_CONTAINER_CHANGE.len()
        );
        assert_eq!(
            packet.smithing_transform_recipes.len(),
            table::SMITHING_TRANSFORM.len()
        );
        assert_eq!(
            packet.smithing_trim_recipes.len(),
            table::SMITHING_TRIM.len()
        );
        assert!(packet.multi_recipes.is_empty());
        assert!(packet.clear_recipes);
    }

    #[test]
    fn every_item_has_its_reference_runtime_id() {
        let ids = reference_ids();
        for i in all_ingredients() {
            match i {
                Ingredient::Exact(e) => {
                    assert_eq!(ids.get(e.item.name()), Some(&e.item.runtime_id()));
                }
                Ingredient::AnyMeta(n) => assert_eq!(ids.get(n.name), Some(&n.runtime_id)),
                Ingredient::Tag(tag) => assert!(tag.starts_with("minecraft:")),
            }
        }
        for s in all_results() {
            assert_eq!(ids.get(s.item.name()), Some(&s.item.runtime_id()));
            assert!(s.count > 0);
        }
        for r in &table::SHAPED {
            assert_eq!(r.grid.len(), usize::from(r.width) * usize::from(r.height));
        }
    }

    #[test]
    fn crafting_data_round_trips_through_the_codec() {
        let shield = i32::from(reference_ids()["minecraft:shield"]);
        let round_trip = |data: CraftingData| {
            let packet = Packet::CraftingData(Box::new(data));
            let mut bytes = Vec::new();
            packet.encode(&mut bytes, shield).unwrap();
            let mut budget = 64 << 20;
            let decoded = Packet::decode(packet.id(), &bytes, &mut budget, shield).unwrap();
            assert_eq!(decoded, packet);
        };
        let mut data = crafting_data();
        let mut whole = Vec::new();
        Packet::CraftingData(Box::new(data.clone()))
            .encode(&mut whole, shield)
            .unwrap();
        // Anchor's decoder takes at most `MAX_LIST_LEN` (1,024) entries per list, fewer than the
        // shapeless list holds, so the shapeless recipes round-trip in parts.
        let shapeless = std::mem::take(&mut data.shapeless_recipes);
        round_trip(data);
        for part in shapeless.chunks(1000) {
            round_trip(CraftingData {
                shapeless_recipes: part.to_vec(),
                ..CraftingData::default()
            });
        }
    }

    #[test]
    fn network_ids_count_from_one_without_gaps() {
        let packet = crafting_data();
        let mut ids: Vec<u32> = packet
            .shaped_recipes
            .iter()
            .map(|r| r.recipe_network_id)
            .chain(packet.shapeless_recipes.iter().map(|r| r.recipe_network_id))
            .chain(
                packet
                    .smithing_transform_recipes
                    .iter()
                    .map(|r| r.recipe_network_id),
            )
            .chain(
                packet
                    .smithing_trim_recipes
                    .iter()
                    .map(|r| r.recipe_network_id),
            )
            .collect();
        let count = ids.len();
        ids.sort_unstable();
        let expected: Vec<u32> = (1..=u32::try_from(count).unwrap()).collect();
        assert_eq!(ids, expected);
        let recipe_ids: BTreeSet<&str> = packet
            .shaped_recipes
            .iter()
            .map(|r| r.recipe_id.as_str())
            .chain(
                packet
                    .shapeless_recipes
                    .iter()
                    .map(|r| r.recipe_id.as_str()),
            )
            .collect();
        assert_eq!(
            recipe_ids.len(),
            packet.shaped_recipes.len() + packet.shapeless_recipes.len()
        );
    }

    fn default_descriptor(name: &str, meta: i32) -> ItemDescriptorCount {
        ItemDescriptorCount {
            descriptor: ItemDescriptor::Default(DefaultItemDescriptor {
                name: name.to_owned(),
                metadata_value: meta,
            }),
            count: 1,
        }
    }

    #[test]
    fn oak_planks_come_from_any_oak_log() {
        let packet = crafting_data();
        let recipe = packet
            .shaped_recipes
            .iter()
            .find(|r| r.input == [default_descriptor("minecraft:oak_log", WILDCARD_META)])
            .unwrap();
        assert_eq!((recipe.width, recipe.height), (1, 1));
        assert_eq!(recipe.block, "crafting_table");
        assert_eq!(recipe.priority, 50);
        let [planks] = recipe.output.as_slice() else {
            panic!("one result expected");
        };
        assert_eq!(planks.count, 4);
        let oak = reference_ids()["minecraft:oak_planks"];
        assert_eq!(planks.item_type.network_id, i32::from(oak));
        assert_ne!(planks.block_runtime_id, 0);
    }

    #[test]
    fn furnace_recipes_are_shapeless_recipes_of_their_block() {
        // PMMP dump: {"block":"furnace","input":{"any_meta":"minecraft:iron_ore"},"result":
        // {"name":"minecraft:iron_ingot","meta":0,"count":1}}.
        let packet = crafting_data();
        let ingot = reference_ids()["minecraft:iron_ingot"];
        let blocks: BTreeSet<&str> = packet
            .shapeless_recipes
            .iter()
            .filter(|r| r.input == [default_descriptor("minecraft:iron_ore", WILDCARD_META)])
            .inspect(|r| {
                assert_eq!(r.output.len(), 1);
                assert_eq!(r.output[0].item_type.network_id, i32::from(ingot));
                assert_eq!(r.output[0].count, 1);
            })
            .map(|r| r.block.as_str())
            .collect();
        assert_eq!(blocks, BTreeSet::from(["blast_furnace", "furnace"]));
        // Furnace recipes follow every crafting recipe.
        let first_furnace = &packet.shapeless_recipes[table::SHAPELESS.len()];
        assert_eq!(first_furnace.block, "furnace");
        assert_eq!(
            first_furnace.recipe_network_id,
            u32::try_from(table::SHAPED.len() + table::SHAPELESS.len() + 1).unwrap()
        );
    }

    #[test]
    fn potion_recipes_use_runtime_ids_and_metas() {
        // PMMP dump: potion meta 0 (water) + nether wart -> potion meta 4 (awkward).
        let ids = reference_ids();
        let potion = i32::from(ids["minecraft:potion"]);
        let wart = i32::from(ids["minecraft:nether_wart"]);
        let packet = crafting_data();
        assert!(packet.potion_recipes.contains(&PotionRecipe {
            input_potion_id: potion,
            input_potion_metadata: 0,
            reagent_item_id: wart,
            reagent_item_metadata: 0,
            output_potion_id: potion,
            output_potion_metadata: 4,
        }));
        let splash = i32::from(ids["minecraft:splash_potion"]);
        let gunpowder = i32::from(ids["minecraft:gunpowder"]);
        assert!(
            packet
                .potion_container_change_recipes
                .contains(&PotionContainerChangeRecipe {
                    input_item_id: potion,
                    reagent_item_id: gunpowder,
                    output_item_id: splash,
                })
        );
    }

    #[test]
    fn firework_stars_keep_their_colour_meta() {
        // PMMP serializes a firework star's colour as its meta, which is not part of the type.
        let star = i32::from(reference_ids()["minecraft:firework_star"]);
        let metas: BTreeSet<u32> = crafting_data()
            .shapeless_recipes
            .iter()
            .flat_map(|r| &r.output)
            .filter(|s| s.item_type.network_id == star)
            .map(|s| s.item_type.metadata_value)
            .collect();
        assert_eq!(metas, (0..16).collect());
    }

    #[test]
    fn exact_block_ingredients_carry_the_legacy_meta() {
        // Every exact block ingredient sends PMMP's legacy state meta, never the wildcard.
        let mut seen = 0;
        for i in all_ingredients() {
            if let Ingredient::Exact(e) = i
                && e.item.block().is_some()
            {
                assert!((0..WILDCARD_META).contains(&e.network_meta));
                seen += 1;
            }
        }
        assert!(seen > 0);
    }
}
